\end{tabular}
\end{table}

\begin{table}[t]
\centering
\small
\caption{AUROC gap (IRT-FIT $-$ best baseline). The gap narrows at higher contamination levels where aberrant patterns are strong enough for binary-level detection.}
\label{tab:gap}
\begin{tabular}{lccc}
\toprule
